"""远征面板 Mixin — 远征收取操作。"""

from __future__ import annotations

import time
from typing import TYPE_CHECKING

from autowsgr.image_resources import Templates
from autowsgr.infra.logger import get_logger
from autowsgr.types import PageName
from autowsgr.ui.map.base import BaseMapPage
from autowsgr.ui.map.data import (
    EXPEDITION_READY_COLOR,
    EXPEDITION_SLOT_PROBES,
    EXPEDITION_SLOT_TOLERANCE,
)
from autowsgr.ui.substate import SubstateSpec
from autowsgr.ui.utils import confirm_operation, wait_for_stable_screen
from autowsgr.vision import ImageChecker, PixelChecker


if TYPE_CHECKING:
    import numpy as np


_log = get_logger('ui')


def _is_expedition_result(screen: np.ndarray) -> bool:
    """判定远征结果页：右下角 "点击继续。" 专用模板。

    不能复用 ``Templates.Symbol.CLICK_TO_CONTINUE``（战斗结算页的 MVP 徽章），
    实机在远征结果页最高只有 0.563，低于 0.85 阈值 —— 4.1 把它当硬门禁后
    每次收取都会超时抛 ``PageDriftError``，游戏卡在结果页直到强制重启。
    """
    return ImageChecker.template_exists(screen, Templates.Symbol.EXPEDITION_CONTINUE)


class ExpeditionPanelMixin(BaseMapPage):
    """Mixin: 远征面板操作 — 远征收取。"""

    # ── 查询 ─────────────────────────────────────────────────────────────

    @staticmethod
    def find_ready_expedition_slot(screen: np.ndarray) -> int | None:
        """检测 4 个远征槽位，返回第一个已完成 (黄色) 的槽位索引。

        Parameters
        ----------
        screen:
            截图 (HxWx3, RGB)。

        Returns
        -------
        int | None
            就绪槽位索引 (0-3)，无就绪则返回 ``None``。
        """
        for i, (px, py) in enumerate(EXPEDITION_SLOT_PROBES):
            actual = PixelChecker.get_pixel(screen, px, py)
            if actual.near(EXPEDITION_READY_COLOR, EXPEDITION_SLOT_TOLERANCE):
                _log.debug(
                    '[UI] 远征槽位 {} 就绪: 实际颜色 {} ≈ 黄色',
                    i + 1,
                    actual.as_rgb_tuple(),
                )
                return i
        return None

    # ── 操作 ─────────────────────────────────────────────────────────────

    def _dismiss_expedition_overlay(self) -> None:
        """尽力清掉远征结果页 / 确认弹窗，避免异常把游戏留在未知 overlay 上。

        4.2 的出逃阶梯没有"点击继续"这一级，结果页一旦残留，后续导航和任务
        会反复识别失败，最终由 ``recover_to_main_or_restart`` 强制重启游戏。
        这里在收取异常时先自己把画面点回可识别状态，成本远低于重启。
        """
        try:
            screen = self._ctrl.screenshot()
        except Exception:
            _log.opt(exception=True).debug('[UI] 远征 overlay 兜底: 截图失败')
            return

        try:
            if ImageChecker.template_exists(screen, Templates.Symbol.EXPEDITION_CONTINUE):
                _log.info('[UI] 远征 overlay 兜底: 点击继续')
                self.click_expedition_skip()
                wait_for_stable_screen(
                    self._ctrl,
                    timeout=1.0,
                    interval=0.1,
                    stable_frames=2,
                    source='远征结果页兜底',
                    stop_event=self._ctx.stop_event,
                )
            if confirm_operation(self._ctrl, must_confirm=False, delay=0.3, timeout=1.5):
                _log.info('[UI] 远征 overlay 兜底: 确认弹窗已清')
        except Exception:
            _log.opt(exception=True).debug('[UI] 远征 overlay 兜底清理失败')

    def collect_expedition(self) -> int:
        """在远征面板收取已完成的远征。

        Returns
        -------
        int
            收取的远征数量。

        Raises
        ------
        NavigationError
            远征通知仍在但 10s 内无法检测到就绪槽位。
        """
        collected = 0
        for _ in range(8):
            # ── 检测就绪槽位 (含等待逻辑) ──
            screen = self._ctrl.screenshot()
            slot_idx = self.find_ready_expedition_slot(screen)
            if slot_idx is None:
                # 无黄色槽位 — 检查上方探测点是否仍报告有远征
                if not self.has_expedition_notification(screen):
                    _log.debug('[UI] 远征收取: 无就绪槽位且无通知，结束')
                    break

                # 上方探测点仍亮 — 等待槽位刷新 (最多 10s)
                _log.debug('[UI] 远征收取: 通知仍在，等待槽位刷新…')
                deadline = time.monotonic() + 10.0
                while time.monotonic() < deadline:
                    time.sleep(0.1)
                    screen = self._ctrl.screenshot()
                    slot_idx = self.find_ready_expedition_slot(screen)
                    if slot_idx is not None:
                        break
                    if not self.has_expedition_notification(screen):
                        _log.debug('[UI] 远征收取: 通知消失，结束')
                        break
                else:
                    from autowsgr.ui.utils import NavigationError

                    raise NavigationError(
                        '远征收取超时: 通知仍在但 10s 内未检测到就绪槽位',
                        screen=screen,
                    )

                if slot_idx is None:
                    break

            slot_pos = EXPEDITION_SLOT_PROBES[slot_idx]
            _log.info(
                '[UI] 远征收取: 点击槽位 {} ({:.4f}, {:.4f})',
                slot_idx + 1,
                *slot_pos,
            )

            try:
                # 1. 点击就绪槽位，并验证远征结果画面出现
                #    结果页用远征自己的 "点击继续。" 模板；战斗结算的
                #    CLICK_TO_CONTINUE 在远征页永远命中不了（实测 0.563）。
                SubstateSpec(
                    page=PageName.MAP.value,
                    substate=f'远征/结果{slot_idx + 1}',
                    checker=_is_expedition_result,
                    timeout=8.0,
                    retries=1,
                    interval=0.25,
                    stable_frames=1,
                ).click(
                    self._ctx,
                    slot_pos,
                    source=f'远征-槽位{slot_idx + 1}',
                    action_name='collect_expedition',
                )

                # 2. 等结果画面动画稳定
                wait_for_stable_screen(
                    self._ctrl,
                    timeout=0.5,
                    interval=0.1,
                    stable_frames=2,
                    source='远征结果画面',
                    stop_event=self._ctx.stop_event,
                )

                # 3. 点击屏幕右侧跳过动画，并验证确认弹窗出现
                SubstateSpec(
                    page=PageName.MAP.value,
                    substate='远征/确认弹窗',
                    checker=lambda screen: ImageChecker.find_any(screen, Templates.Confirm.all())
                    is not None,
                    timeout=3.0,
                    retries=1,
                    interval=0.2,
                    stable_frames=1,
                ).apply(
                    self._ctx,
                    self.click_expedition_skip,
                    source=f'远征-槽位{slot_idx + 1} 跳过动画',
                    action_name='click_expedition_skip',
                )

                # 4. 确认弹窗
                confirm_operation(
                    self._ctrl,
                    must_confirm=True,
                    delay=0.5,
                    confidence=0.9,
                    timeout=5.0,
                )

                # 5. 等待回到地图页面并登记子状态
                SubstateSpec(
                    page=PageName.MAP.value,
                    substate='远征/已收取',
                    checker=self.is_current_page,
                    timeout=5.0,
                    retries=1,
                    interval=0.3,
                    stable_frames=2,
                ).wait(self._ctx, source='远征收取')
            except Exception:
                # 任一步失败都先点掉整屏结果页；否则后续导航/任务全部识别
                # 失败，最终触发强制重启游戏 (SL)，新远征也不会派出。
                self._dismiss_expedition_overlay()
                raise

            collected += 1

        _log.info('[UI] 远征收取: {} 支', collected)
        return collected
